const CRA = 'Canada Revenue Agency', RQ = 'Revenu Québec', D = '2026-11-10';
const PERSON = kind('individual', 'sole_prop');
const CORP = kind('corporation');
const TRUST = kind('trust');
const PSHIP = kind('partnership');
const NP = kind('nonprofit');
const BIZ = kind('sole_prop', 'partnership', 'corporation', 'trust', 'nonprofit');
const selfEmployed = any(kind('sole_prop'), yes('ca_selfemp'));
const notSelfEmployed = all(kind('individual'), not(yes('ca_selfemp')));
const charity = is('ca_np_type', 'charity');
const npo = is('ca_np_type', 'npo');
const incorporated = any(CORP, all(NP, yes('ca_npo_corp')));
